// generated by overlord sync; changes here are overwritten
// Runs `overlord sync --quiet` when OpenCode creates a top-level session: the
// OpenCode counterpart of the SessionStart hook Overlord installs for Claude
// Code and Codex.
import { Plugin } from "@opencode/plugin"
import { spawn } from "node:child_process"

export default Plugin.define({
  id: "overlord-sync",
  setup: (ctx) => {
    const controller = new AbortController()
    ;(async () => {
      for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
        // Subagent sessions carry a parentID; their parent already synced.
        if (event.type !== "session.created" || event.data.parentID) continue
        spawn("overlord", ["sync", "--quiet"], { stdio: "ignore", detached: true }).on("error", () => {}).unref()
      }
    })().catch(() => {})
    return () => controller.abort()
  },
})
